import { useState } from "react";
import axios from "axios";

function MedicalForm() {
  const [age, setAge] = useState("");
  const [gender, setGender] = useState("");
  const [duration, setDuration] = useState("");
  const [issues, setIssues] = useState("");
  const [result, setResult] = useState(null);

  const submit = async () => {
    const res = await axios.post("http://127.0.0.1:5000/predict_text", {
      age,
      gender,
      duration,
      text: issues
    });

    setResult(res.data);
  };

  return (
    <div style={{padding:"30px", fontFamily:"Arial"}}>
      <h1>🩺 AI Health Symptom Form</h1>

      Age: <input type="number" onChange={e=>setAge(e.target.value)} /><br/><br/>

      Gender:
      <select onChange={e=>setGender(e.target.value)}>
        <option>Select</option>
        <option>Male</option>
        <option>Female</option>
      </select><br/><br/>

      Duration (days):
      <input type="number" onChange={e=>setDuration(e.target.value)} /><br/><br/>

      <h3>Describe your health issues</h3>
      <textarea 
        rows="4" 
        cols="50"
        placeholder="Example: I have fever, headache and stomach pain"
        onChange={e=>setIssues(e.target.value)}
      ></textarea>
      <br/><br/>

      <button onClick={submit}>Submit</button>

      {result && (
        <div style={{marginTop:"20px", border:"2px solid black", padding:"15px"}}>
          <h2>🔍 Prediction Result</h2>
          
          <h3>Disease: <strong>{result.disease}</strong></h3>
          <h3>Confidence: {result.confidence}%</h3>

          <hr/>
          <h3>Urgency Level: <span style={{color: result.urgency === "High" ? "red" : result.urgency === "Medium" ? "orange" : "green"}}>{result.urgency}</span></h3>
          
          {result.symptoms_detected && (
            <p><strong>Symptoms Detected:</strong> {result.symptoms_detected.join(", ")}</p>
          )}

          {result.urgency === "High" && (
            <h2 style={{color:"red"}}>⚠️ Visit Doctor Immediately!</h2>
          )}
        </div>
      )}
    </div>
  );
}

export default MedicalForm;
